from collections import defaultdict

orders = [
    {"order_id": 1, "region": "es", "amount": 120.0},
    {"order_id": 2, "region": "es", "amount": 80.5},
    {"order_id": 3, "region": "en", "amount": 200.0},
    {"order_id": 4, "region": "en", "amount": 150.0},
]

def oltp_lookup(order_id):
    return next(o for o in orders if o["order_id"] == order_id)

def olap_rollup():
    totals = defaultdict(float)
    for o in orders:
        totals[o["region"]] += o["amount"]
    return dict(sorted(totals.items()))

print("OLTP lookup order 3:", oltp_lookup(3))
print("OLAP rollup by region:", olap_rollup())
